import { getTodos } from '../core-engine/core-engine.ts';

export function render(container: HTMLElement) {
  const mainContainer = document.createElement('div');
  mainContainer.style.cssText = `
    background: #f0f0f0;
    padding: 20px;
    border-radius: 8px;
  `;

  const topbar = document.createElement('div');
  topbar.className = 'topbar';
  mainContainer.appendChild(topbar);

  const addButton = document.createElement('button');
  addButton.id = 'addTodoButton';
  addButton.textContent = 'Add Todo';
  addButton.addEventListener('click', addTodo);
  topbar.appendChild(addButton);

  const searchBar = document.createElement('input');
  searchBar.id = 'searchInput';
  searchBar.classList.add('search-input');
  topbar.appendChild(searchBar);

  const taskList = document.createElement('div');
  taskList.className = 'task-list';
  mainContainer.appendChild(taskList);

  const prioritySlider = document.createElement('input');
  prioritySlider.id = 'prioritySlider';
  prioritySlider.classList.add('priority-slider');
  topbar.appendChild(prioritySlider);

  const dueDateInput = document.createElement('input');
  dueDateInput.type = 'date';
  dueDateInput.id = 'dueDateInput';
  topbar.appendChild(dueDateInput);

  const actionsButton = document.createElement('button');
  actionsButton.id = 'actionsButton';
  actionsButton.textContent = 'Actions';
  actionsButton.addEventListener('click', listSelectedTodos);
  topbar.appendChild(actionsButton);

  container.appendChild(mainContainer);
}

export function addTodo() {
  const title = document.getElementById('searchInput') as HTMLInputElement;
  if (!title) return;
  const titleValue = title.value.trim();
  if (!titleValue) return;
  addTodoToStorage(titleValue);
  title.value = '';
  updateTaskList();
}

export function addTodoToStorage(title: string) {
  const todos = JSON.parse(localStorage.getItem('todos') || '[]');
  const newTodo = { id: Date.now().toString(), title, completed: false };
  todos.push(newTodo);
  localStorage.setItem('todos', JSON.stringify(todos));
}

export function updateTaskList() {
  const taskList = document.querySelector('.task-list') as HTMLDivElement;
  if (!taskList) return;
  taskList.innerHTML = '';
  const todos = getTodosFromStorage();
  todos.forEach((todo) => {
    const card = document.createElement('div');
    card.className = 'task-card';
    card.innerHTML = `
      <div class="task-title">${todo.title}</div>
      <div class="task-status">${todo.completed ? '✅' : '❌'}</div>
      <div class="task-actions">
        <button class="task-edit" onclick="editTodo('${todo.id}')">✏️</button>
        <button class="task-delete" onclick="deleteTodo('${todo.id}')">🗑️</button>
      </div>
    `;
    taskList.appendChild(card);
  });
}

export function getTodosFromStorage() {
  return JSON.parse(localStorage.getItem('todos') || '[]');
}

export function toggleTodo(id: string) {
  const todos = getTodosFromStorage();
  const todo = todos.find((t) => t.id === id);
  if (!todo) return;
  todo.completed = !todo.completed;
  localStorage.setItem('todos', JSON.stringify(todos));
  updateTaskList();
}

export function deleteTodo(id: string) {
  const todos = getTodosFromStorage();
  const filteredTodos = todos.filter((t) => t.id !== id);
  localStorage.setItem('todos', JSON.stringify(filteredTodos));
  updateTaskList();
}

export function listSelectedTodos() {
  const selectedTodos = getTodosFromStorage().filter((t) => t.completed);
  if (selectedTodos.length === 0) {
    alert('No completed todos selected.');
    return;
  }
  const list = document.createElement('div');
  list.className = 'selected-todos';
  selectedTodos.forEach((todo) => {
    const card = document.createElement('div');
    card.className = 'task-card';
    card.innerHTML = `
      <div class="task-title">${todo.title}</div>
      <div class="task-status">✅</div>
      <div class="task-actions">
        <button class="task-edit" onclick="editTodo('${todo.id}')">✏️</button>
        <button class="task-delete" onclick="deleteTodo('${todo.id}')">🗑️</button>
      </div>
    `;
    list.appendChild(card);
  });
  document.body.appendChild(list);
}

