export const handleInput = (input: string): void => {
  if (!input) {
    console.error('Input is empty');
    return;
  }

  const todos = getTodos();
  const newTodo: { id: string; title: string; completed: boolean } = { id: Date.now().toString(), title: input, completed: false };
  todos.push(newTodo);
  saveTodos(todos);
  console.log('Input handled successfully');
};

