export interface Task {
  id: number;
  title: string;
  completed: boolean;
  priority: 'high' | 'medium' | 'low';
}

export interface TodoState {
  todos: Task[];
  filter: 'all' | 'active' | 'completed';
  search: string;
}

export function saveToStorage(state: TodoState): void {
  try {
    const data = JSON.stringify(state);
    localStorage.setItem('todoState', data);
  } catch (error) {
    console.error('Failed to save to storage:', error);
  }
}

export function loadFromStorage(): TodoState {
  try {
    const stored = localStorage.getItem('todoState');
    if (stored) {
      return JSON.parse(stored) as TodoState;
    }
  } catch (error) {
    console.error('Failed to load from storage:', error);
  }
  return { todos: [], filter: 'all', search: '' };
}

export function addTask(title: string): Task {
  const todos = loadFromStorage().todos;
  const id = todos.length + 1;
  const task: Task = { id, title, completed: false, priority: 'medium' };
  todos.push(task);
  saveToStorage({ todos, filter: 'all', search: '' });
  return task;
}

export function deleteTask(id: number): void {
  const todos = loadFromStorage().todos;
  todos.splice(todos.findIndex(t => t.id === id), 1);
  saveToStorage({ todos, filter: 'all', search: '' });
}

export function toggleTask(id: number): void {
  const todos = loadFromStorage().todos;
  const task = todos.find(t => t.id === id);
  if (task) {
    task.completed = !task.completed;
    saveToStorage({ todos, filter: 'all', search: '' });
  }
}

export function changeFilter(filter: 'all' | 'active' | 'completed'): void {
  saveToStorage({ todos: loadFromStorage().todos, filter, search: '' });
}

export function changeSearch(query: string): void {
  saveToStorage({ todos: loadFromStorage().todos, filter: 'all', search: query });
}

export function getFilteredTodos(todos: Task[], filter: 'all' | 'active' | 'completed', search: string): Task[] {
  if (filter === 'active') {
    return todos.filter(t => !t.completed);
  } else if (filter === 'completed') {
    return todos.filter(t => t.completed);
  }
  return todos.filter(t => t.title.toLowerCase().includes(search.toLowerCase()));
}

